func main(){if len(os.Args)>=3&&os.Args[1]=="--child"{child(os.Args[2]);return};root:=filepath.Join(os.TempDir(),"ThreatBoxAccuracy",fmt.Sprintf("process-tree-%d-%d",os.Getpid(),time.Now().UnixNano()));if e:=os.MkdirAll(root,0700);e!=nil{emit(Rec{Fixture:"process-tree",Role:"parent",PID:os.Getpid(),PPID:os.Getppid(),Root:root,Error:e.Error()});os.Exit(2)};exe,e:=os.Executable();if e!=nil{emit(Rec{Fixture:"process-tree",Role:"parent",PID:os.Getpid(),PPID:os.Getppid(),Root:root,Error:e.Error()});os.Exit(2)};cmd:=exec.Command(exe,"--child",root);out,runErr:=cmd.CombinedOutput();code:=0;if cmd.ProcessState!=nil{code=cmd.ProcessState.ExitCode()};r:=Rec{Fixture:"process-tree",Role:"parent",PID:os.Getpid(),PPID:os.Getppid(),Root:root,OK:runErr==nil,ExitCode:code};if runErr!=nil{r.Error=runErr.Error()+": "+string(out)};emit(r);if len(out)>0{fmt.Print(string(out))};if runErr!=nil{os.Exit(3)}}
func child(root string){p:=filepath.Join(root,"child-marker.txt");e:=os.WriteFile(p,[]byte("benign child process marker\n"),0600);r:=Rec{Fixture:"process-tree",Role:"child",PID:os.Getpid(),PPID:os.Getppid(),Root:root,Marker:p,OK:e==nil};if e!=nil{r.Error=e.Error()};emit(r);if e!=nil{os.Exit(4)}}
